package com.yazaki.printingservice.api;
import java.net.URI; import java.time.Instant; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import com.yazaki.printingservice.api.dto.PrintJobDtos; import com.yazaki.printingservice.application.PrintJobService; import com.yazaki.printingservice.domain.model.*; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid;
@RestController @RequestMapping("/api/v1/print-jobs") @Tag(name="Print Jobs")
public class PrintJobController {
 private final PrintJobService service; public PrintJobController(PrintJobService service){this.service=service;}
 @PostMapping @Operation(summary="Create an idempotent print job") ResponseEntity<PrintJobDtos.Job> create(@Valid @RequestBody PrintJobDtos.Create in){var r=service.create(in);return r.created()?ResponseEntity.created(URI.create("/api/v1/print-jobs/"+r.job().id())).body(r.job()):ResponseEntity.ok(r.job());}
 @GetMapping Page<PrintJobDtos.Job> list(@RequestParam(required=false)PrintJobStatus status,@RequestParam(required=false)PrinterType type,@RequestParam(required=false)UUID printerId,@RequestParam(required=false)String orderId,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant from,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant to,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable page){return service.search(status,type,printerId,orderId,from,to,page);}
 @GetMapping("/{id}") PrintJobDtos.Job get(@PathVariable UUID id){return service.get(id);} @GetMapping("/{id}/events") List<PrintJobDtos.Event> events(@PathVariable UUID id){return service.events(id);}
 @PostMapping("/{id}/retry") PrintJobDtos.Job retry(@PathVariable UUID id){return service.retry(id);} @PostMapping("/{id}/reprint") @ResponseStatus(HttpStatus.CREATED) PrintJobDtos.Job reprint(@PathVariable UUID id){return service.reprint(id);} @PostMapping("/{id}/cancel") PrintJobDtos.Job cancel(@PathVariable UUID id){return service.cancel(id);}
}
